import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import * as nodeUtil from "node:util";

export function runtimeIssue(version = process.versions.node) {
  const [major, minor] = version.split(".").map(Number);
  return !Number.isInteger(major) || major < 22 || (major === 22 && minor < 13)
    ? "Node.js 22.13 or later is required. Install Node.js 24 LTS, reopen your terminal, then run npm ci."
    : null;
}

// Match Next's file precedence. Values generated by setup are literal base64url;
// intentionally leave advanced dotenv interpolation to Next itself.
export function readConfiguration(root, environment = process.env, mode = environment.NODE_ENV || "development") {
  const names = mode === "test"
    ? [".env", ".env.test", ".env.test.local"]
    : [".env", `.env.${mode}`, ".env.local", `.env.${mode}.local`];
  let secret;
  let source;
  let fileEnvironment = {};
  for (const name of names) {
    const path = join(root, name);
    if (!existsSync(path)) continue;
    const parsed = nodeUtil.parseEnv(readFileSync(path, "utf8"));
    fileEnvironment = { ...fileEnvironment, ...parsed };
    if (Object.hasOwn(parsed, "SESSION_SECRET")) {
      secret = parsed.SESSION_SECRET;
      source = name;
    }
  }
  if (environment.SESSION_SECRET !== undefined) {
    secret = environment.SESSION_SECRET;
    source = "server environment";
  }
  return { secret, source, environment: { ...fileEnvironment, ...environment } };
}

export function secretIssue(secret) {
  return typeof secret !== "string" || secret.trim().length < 32
    ? "SESSION_SECRET needs a stable random value of at least 32 characters. Run npm run setup for a new local installation. Existing nonempty secrets are never replaced automatically."
    : null;
}

/** Select storage without connecting or including a credential in an error. */
export function storageMode(environment) {
  const requested = environment.TREG_STORAGE;
  if (requested && !["sqlite", "postgres"].includes(requested))
    throw new Error("TREG_STORAGE must be sqlite or postgres.");
  const databaseUrl = environment.DATABASE_URL?.trim();
  const selected = requested || (databaseUrl ? "postgres" : "sqlite");
  if (environment.VERCEL === "1" && selected !== "postgres")
    throw new Error("Vercel requires durable Postgres storage and DATABASE_URL; SQLite is for a persistent local host.");
  if (selected === "postgres") {
    let url;
    try { url = new URL(databaseUrl || ""); } catch { /* Return only the safe configuration error below. */ }
    if (!url || !["postgres:", "postgresql:"].includes(url.protocol) || !url.hostname)
      throw new Error("Postgres storage requires a valid private DATABASE_URL using postgres:// or postgresql://. Its value is hidden.");
  }
  return selected;
}
